"doctor_idErr"></div></div><div class="form-group col-md-8"><label for="role_ids">Roles</label><select class="custom-select" id="role_ids" name="role_ids[]" multiple required><?php foreach ($roles as $role): ?><option value="<?= (int) $role['id'] ?>"><?= esc($role['role_name']) ?></option><?php endforeach; ?></select><small class="form-text text-muted">Use Ctrl/Cmd to select multiple roles.</small><div class="validation-error" id="role_ids[]Err"></div></div></div><button class="btn btn-primary save-user" type="submit">Create user</button> <button class="btn btn-light reset-user" type="button">Clear</button></form></div></div><?php endif; ?>
