<?= $this->section('scripts') ?><script>
$(function(){const form=$('#user-form');const alertBox=$('#access-alert');function notify(ok,msg){alertBox.html('<div class="alert '+(ok?'alert-success':'alert-danger')+' alert-dismissible fade show" role="alert">'+$('<div>').text(msg).html()+'<button type="button" class="close" data-dismiss="alert" aria-label="Close"><span aria-hidden="true">&times;</span></button></div>');}function resetForm(){form[0].reset();form.find('[name=id]').val('');form.find('[name="role_ids[]"]').val([]);$('#user-editor-title').text('Create user');form.find('.save-user').text('Create user');$('#password').prop('required',true);bindCountryCodeToggles('#user-form');}function submitForm(url){const button=form.find('.save-user');button.prop('disabled',true).addClass('access-loading').text('Saving...');ajaxRequest({url:url,data:form.serialize(),complete:function(){button.prop('disabled',false).removeClass('access-loading');},success:function(r){if(r.status){notify(true,r.msg);setTimeout(function(){location.reload();},650);}else{notify(false,r.msg);}}});}$('#new-user,.reset-user').on('click',function(){resetForm();$('#user-editor')[0].scrollIntoView({behavior:'smooth',block:'start'});});form.on('submit',function(e){e.preventDefault();submitForm(form.find('[name=id]').val()?'<?= base_url('admin/access/users/update') ?>/'+form.find('[name=id]').val():'<?= base_url('admin/access/users/create') ?>');});$('.edit-user').on('click',function(){const u=$(this).data('user');form.find('[name=id]').val(u.id);form.find('[name=username]').val(u.username);form.find('[name=email]').val(u.email||'');form.find('[name=mobile]').val(u.mobile||'');form.find('[name="telephone_country_code_id"]').val(u.telephone_country_code_id||'').selectpicker('refresh');form.find('[name=telephone_country_name]').val(u.telephone_country_name||'');form.find('[name=country_code]').val(u.telephone_country_code||'');form.find('[name=country_code_manual]').prop('checked',!u.telephone_country_code_id&&!!u.telephone_country_code);bindCountryCodeToggles('#user-form');form.find('[name=doctor_id]').val(u.doctor_id||0);form.find('[name=status]').val(u.status);form.find('[name="role_ids[]"]').val((u.role_ids||'').split(',').filter(Boolean));$('#password').prop('required',false);$('#user-editor-title').text('Edit user');form.find('.save-user').text('Save changes');$('#user-editor')[0].scrollIntoView({behavior:'smooth',block:'start'});});$('.delete-user').on('click',function(){const id=$(this).data('id');if(!confirm('Disable this account?'))return;ajaxRequest({url:'<?= base_url('admin/access/users/delete') ?>/'+id,data:{csrf_rtn:$('input[name="csrf_rtn"]').first().val()},success:function(r){r.status?location.reload():notify(false,r.msg);}});});$('#user-search,#user-status-filter').on('input change',function(){const q=$('#user-search').val().toLowerCase();const s=$('#user-status-filter').val();let n=0;$('#users-table tbody tr').each(function(){const row=$(this);if(row.hasClass('access-empty-row'))return;const show=(!q||row.data('search').indexOf(q)!==-1)&&(!s||String(row.data('status'))===s);row.toggle(show);if(show)n++;});$('#user-count').text(n);});resetForm();});
</script><?= $this->endSection() ?>
